        sbCtx.fillRect(bx, by, 29, 13);
        sbCtx.fillStyle = "rgba(255,255,255,0.14)";
        sbCtx.fillRect(bx, by, 29, 1.5);
        sbCtx.fillStyle = "rgba(40,34,26,0.14)";
        sbCtx.fillRect(bx, by + 11.5, 29, 1.5);
