      group,
      building,
      trimMat,
      terrainY,
      getTerrainHeightFn,
      arch,
      addBox,
      storyH,
      cosArch,
      sinArch,
      wallZ,
      frontIndentZ,
      frontWingZ,
      lowerPlazaY,
      lowerNumSteps,
      lowerStepRise,
      lowerStepRun,
