      sinT,
      getConcreteTopY,
      washX,
      portX,
      portDepth,
      portW,
      deckY,
      whiteRoofMat,
      creamBrickSolidMat,
      plinthConcreteMat,
      slateGableMat,
      plazaConcreteMat,
      whiteCurbMat,
      turfMat,
      darkMetalMat,
      galvSteelMat,
      blueTreadMat,
      bronzePlaqueMat,
      globeMat,
      glassMat,
      weatheredStuccoMat,
      rearBoxStuccoMat,
