    bollardCap.position.y = 0.87;
    bollardGrp.add(bollardCap);
    arch.add(bollardGrp);
    addBox(0.05, 2.45, 0.05, galvSteelMat, -1.4, 1.45, frontZ + 6.18);
    addBox(0.32, 0.46, 0.02, whiteTrimMat, -1.4, 2.35, frontZ + 6.18);
