    const poleMesh = new Mesh(new CylinderGeometry(0.09, 0.11, 7.8, 12), blackIronMat);
    poleMesh.position.set(medCx + 1.25, landingY + 3.9, medCz - 2.75);
    poleMesh.castShadow = true;
    arch.add(poleMesh);
    const stairX = 26.4;
